"use client"

import * as React from "react"
import {
  AppleIcon,
  ClockIcon,
  FlagIcon,
  HandIcon,
  HashIcon,
  LightbulbIcon,
  PawPrintIcon,
  PlaneIcon,
  SmileIcon,
  TrophyIcon,
  type LucideIcon,
} from "lucide-react"

import { useControllableState } from "@/registry/default/hooks/use-controllable-state"
import {
  addRecent,
  buildSections,
  layoutSections,
  loadEmojis,
  moveCell,
  readPreferences,
  RECENT_SECTION_ID,
  searchEmojis,
  withSkinTone,
  writePreferences,
  type Emoji,
  type EmojiCell,
  type SkinTone,
} from "@/registry/default/lib/emoji-picker"
import { cn } from "@/registry/default/lib/utils"
import { Input } from "@/registry/default/ui/input"

const COLUMNS = 8

const SECTION_ICONS: Record<string, LucideIcon> = {
  [RECENT_SECTION_ID]: ClockIcon,
  "0": SmileIcon,
  "1": HandIcon,
  "3": PawPrintIcon,
  "4": AppleIcon,
  "5": PlaneIcon,
  "6": TrophyIcon,
  "7": LightbulbIcon,
  "8": HashIcon,
  "9": FlagIcon,
}

const SKIN_TONES: { tone: SkinTone; emoji: string; label: string }[] = [
  { tone: 0, emoji: "✋", label: "Default" },
  { tone: 1, emoji: "✋🏻", label: "Light" },
  { tone: 2, emoji: "✋🏼", label: "Medium-light" },
  { tone: 3, emoji: "✋🏽", label: "Medium" },
  { tone: 4, emoji: "✋🏾", label: "Medium-dark" },
  { tone: 5, emoji: "✋🏿", label: "Dark" },
]

const EmojiRow = React.memo(function EmojiRow({
  emojis,
  row,
  tabColumn,
  skinTone,
}: {
  emojis: Emoji[]
  row: number
  tabColumn: number | null
  skinTone: SkinTone
}) {
  return (
    <div
      role="row"
      className="grid grid-cols-8 [contain-intrinsic-size:auto_2.25rem] [content-visibility:auto]"
    >
      {emojis.map((emoji, column) => (
        <div key={emoji.hexcode} role="gridcell">
          <button
            type="button"
            data-row={row}
            data-column={column}
            tabIndex={column === tabColumn ? 0 : -1}
            aria-label={emoji.label}
            title={emoji.label}
            className="flex aspect-square w-full items-center justify-center rounded-md text-xl outline-none hover:bg-accent focus-visible:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:ring-inset"
          >
            {withSkinTone(emoji, skinTone)}
          </button>
        </div>
      ))}
    </div>
  )
})

function EmojiPicker({
  onSelect,
  skinTone,
  defaultSkinTone = 0,
  onSkinToneChange,
  className,
  "aria-label": ariaLabel = "Emoji picker",
  ...props
}: Omit<React.ComponentProps<"div">, "onSelect"> & {
  onSelect?: (emoji: string) => void
  skinTone?: SkinTone
  defaultSkinTone?: SkinTone
  onSkinToneChange?: (skinTone: SkinTone) => void
}) {
  const id = React.useId()
  const gridRef = React.useRef<HTMLDivElement>(null)
  const searchRef = React.useRef<HTMLInputElement>(null)
  const [library, setLibrary] = React.useState<{
    emojis: Emoji[]
    recent: string[]
  } | null>(null)
  const [hasFailed, setHasFailed] = React.useState(false)
  const [storedSkinTone, setStoredSkinTone] = React.useState<SkinTone>()
  const [query, setQuery] = React.useState("")
  const [activeCell, setActiveCell] = React.useState<EmojiCell>({
    row: 0,
    column: 0,
  })
  const { value: tone, setValue: setTone } = useControllableState({
    value: skinTone ?? storedSkinTone,
    defaultValue: defaultSkinTone,
    onChange: (next: SkinTone) => {
      setStoredSkinTone(next)
      writePreferences({ ...readPreferences(), skinTone: next })
      onSkinToneChange?.(next)
    },
  })

  React.useEffect(() => {
    let isCurrent = true
    loadEmojis()
      .then((emojis) => {
        if (!isCurrent) return
        const preferences = readPreferences()
        setLibrary({ emojis, recent: preferences.recent })
        setStoredSkinTone(preferences.skinTone)
      })
      .catch(() => {
        if (isCurrent) setHasFailed(true)
      })
    return () => {
      isCurrent = false
    }
  }, [])

  const needle = query.trim()
  const layout = React.useMemo(() => {
    if (!library) return layoutSections([], COLUMNS)
    const sections = needle
      ? [
          {
            id: "results",
            label: "Search results",
            emojis: searchEmojis(library.emojis, needle),
          },
        ]
      : buildSections(library.emojis, library.recent)
    return layoutSections(sections, COLUMNS)
  }, [library, needle])

  const resultCount = needle ? (layout.sections[0]?.emojis.length ?? 0) : null
  const tabCell = layout.rows[activeCell.row]?.[activeCell.column]
    ? activeCell
    : { row: 0, column: 0 }

  function focusCell(cell: EmojiCell) {
    setActiveCell(cell)
    gridRef.current
      ?.querySelector<HTMLElement>(
        `[data-row="${cell.row}"][data-column="${cell.column}"]`
      )
      ?.focus()
  }

  function pick(emoji: Emoji) {
    const preferences = readPreferences()
    writePreferences({
      ...preferences,
      recent: addRecent(preferences.recent, emoji.hexcode),
    })
    onSelect?.(withSkinTone(emoji, tone))
  }

  function cellOf(target: EventTarget) {
    const button = (target as HTMLElement).closest<HTMLElement>("[data-row]")
    return button
      ? {
          row: Number(button.dataset.row),
          column: Number(button.dataset.column),
        }
      : null
  }

  function handleGridKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    const cell = cellOf(event.target)
    if (!cell) return
    const next = moveCell(
      layout.rows.map((row) => row.length),
      layout.sections.map((section) => section.firstRow),
      cell,
      event.key,
      event.ctrlKey || event.metaKey
    )
    if (!next) return
    event.preventDefault()
    if (event.key === "ArrowUp" && cell.row === 0) searchRef.current?.focus()
    else focusCell(next)
  }

  function handleSearchKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === "ArrowDown") {
      event.preventDefault()
      focusCell(tabCell)
    }
    if (event.key === "Enter" && needle && layout.rows[0]) {
      event.preventDefault()
      pick(layout.rows[0][0])
    }
  }

  function scrollToSection(sectionId: string) {
    const grid = gridRef.current
    const section = document.getElementById(`${id}-${sectionId}`)
    if (grid && section) grid.scrollTop = section.offsetTop
  }

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      data-slot="emoji-picker"
      className={cn(
        "flex h-96 w-80 flex-col gap-2 rounded-lg border bg-popover p-2 text-popover-foreground",
        className
      )}
      {...props}
    >
      <Input
        ref={searchRef}
        type="search"
        aria-label="Search emoji"
        placeholder="Search emoji"
        value={query}
        onChange={(event) => {
          setQuery(event.target.value)
          setActiveCell({ row: 0, column: 0 })
          if (gridRef.current) gridRef.current.scrollTop = 0
        }}
        onKeyDown={handleSearchKeyDown}
        className="h-8"
      />
      {!needle && layout.sections.length > 0 && (
        <div aria-hidden className="flex justify-between">
          {layout.sections.map((section) => {
            const Icon = SECTION_ICONS[section.id]
            return (
              <button
                key={section.id}
                type="button"
                tabIndex={-1}
                title={section.label}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => scrollToSection(section.id)}
                className="flex size-7 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-accent-foreground [&_svg]:size-4"
              >
                <Icon />
              </button>
            )
          })}
        </div>
      )}
      {layout.rows.length === 0 ? (
        <p className="min-h-0 flex-1 p-2 text-sm text-muted-foreground">
          {hasFailed
            ? "Emoji failed to load"
            : library
              ? "No emoji found"
              : "Loading emoji"}
        </p>
      ) : (
        <div
          ref={gridRef}
          role="grid"
          aria-label="Emoji"
          aria-colcount={COLUMNS}
          onKeyDown={handleGridKeyDown}
          onFocus={(event) => {
            const cell = cellOf(event.target)
            if (cell) setActiveCell(cell)
          }}
          onClick={(event) => {
            const cell = cellOf(event.target)
            if (cell) pick(layout.rows[cell.row][cell.column])
          }}
          className="relative min-h-0 flex-1 overflow-y-auto"
        >
          {layout.sections.map((section) => (
            <div
              key={section.id}
              id={`${id}-${section.id}`}
              role="rowgroup"
              aria-labelledby={`${id}-${section.id}-label`}
            >
              <div
                id={`${id}-${section.id}-label`}
                role="presentation"
                className="sticky top-0 z-10 bg-popover py-1 text-xs font-medium text-muted-foreground"
              >
                {section.label}
              </div>
              {layout.rows
                .slice(section.firstRow, section.firstRow + section.rowCount)
                .map((emojis, offset) => {
                  const row = section.firstRow + offset
                  return (
                    <EmojiRow
                      key={row}
                      emojis={emojis}
                      row={row}
                      tabColumn={row === tabCell.row ? tabCell.column : null}
                      skinTone={tone}
                    />
                  )
                })}
            </div>
          ))}
        </div>
      )}
      <fieldset className="flex items-center justify-between">
        <legend className="sr-only">Skin tone</legend>
        {SKIN_TONES.map((option) => (
          <label
            key={option.tone}
            title={`${option.label} skin tone`}
            className="relative flex size-7 cursor-pointer items-center justify-center rounded-md text-base has-checked:bg-accent has-focus-visible:ring-[3px] has-focus-visible:ring-ring/50"
          >
            <input
              type="radio"
              name={`${id}-skin-tone`}
              className="sr-only"
              checked={tone === option.tone}
              onChange={() => setTone(option.tone)}
            />
            <span aria-hidden>{option.emoji}</span>
            <span className="sr-only">{option.label}</span>
          </label>
        ))}
      </fieldset>
      <span role="status" className="sr-only">
        {resultCount === null
          ? ""
          : `${resultCount} ${resultCount === 1 ? "result" : "results"}`}
      </span>
    </div>
  )
}

export { EmojiPicker, type SkinTone }

export type SkinTone = 0 | 1 | 2 | 3 | 4 | 5

export type Emoji = {
  hexcode: string
  emoji: string
  label: string
  tags: string[]
  group: number
  order: number
  version: number
  skins?: { emoji: string; tone?: number | number[] }[]
}

export type EmojiSection = { id: string; label: string; emojis: Emoji[] }

export type EmojiCell = { row: number; column: number }

export type EmojiPreferences = { recent: string[]; skinTone?: SkinTone }

export const RECENT_SECTION_ID = "recent"

const EMOJI_GROUPS = [
  { id: 0, label: "Smileys & emotion" },
  { id: 1, label: "People & body" },
  { id: 3, label: "Animals & nature" },
  { id: 4, label: "Food & drink" },
  { id: 5, label: "Travel & places" },
  { id: 6, label: "Activities" },
  { id: 7, label: "Objects" },
  { id: 8, label: "Symbols" },
  { id: 9, label: "Flags" },
]

const WIDELY_SUPPORTED_EMOJI_VERSION = 15
const MAX_RECENT = 16
const STORAGE_KEY = "drift-ui:emoji-picker"

let emojiRequest: Promise<Emoji[]> | undefined

function isPickable(emoji: Emoji) {
  return (
    EMOJI_GROUPS.some((group) => group.id === emoji.group) &&
    emoji.version <= WIDELY_SUPPORTED_EMOJI_VERSION
  )
}

export function loadEmojis() {
  emojiRequest ??= import("emojibase-data/en/data.json")
    .then(({ default: data }) =>
      (data as unknown as Emoji[])
        .filter(isPickable)
        .sort((first, second) => first.order - second.order)
    )
    .catch((error) => {
      emojiRequest = undefined
      throw error
    })
  return emojiRequest
}

export function searchEmojis(emojis: Emoji[], query: string) {
  const needle = query.trim().toLowerCase()
  if (!needle) return emojis
  return emojis.filter(
    (emoji) =>
      emoji.label.toLowerCase().includes(needle) ||
      emoji.tags.some((tag) => tag.startsWith(needle))
  )
}

export function withSkinTone(emoji: Emoji, skinTone: SkinTone) {
  return (
    emoji.skins?.find((skin) => skin.tone === skinTone)?.emoji ?? emoji.emoji
  )
}

export function buildSections(emojis: Emoji[], recent: string[]) {
  const recentEmojis = recent.flatMap(
    (hexcode) => emojis.find((emoji) => emoji.hexcode === hexcode) ?? []
  )
  const sections: EmojiSection[] = EMOJI_GROUPS.map((group) => ({
    id: String(group.id),
    label: group.label,
    emojis: emojis.filter((emoji) => emoji.group === group.id),
  }))

  return recentEmojis.length > 0
    ? [
        {
          id: RECENT_SECTION_ID,
          label: "Recently used",
          emojis: recentEmojis,
        },
        ...sections,
      ]
    : sections
}

export function layoutSections(sections: EmojiSection[], columns: number) {
  const rows: Emoji[][] = []
  const laidOut = sections
    .filter((section) => section.emojis.length > 0)
    .map((section) => {
      const firstRow = rows.length
      for (let index = 0; index < section.emojis.length; index += columns) {
        rows.push(section.emojis.slice(index, index + columns))
      }
      return { ...section, firstRow, rowCount: rows.length - firstRow }
    })

  return { rows, sections: laidOut }
}

export function moveCell(
  rowLengths: number[],
  sectionStarts: number[],
  { row, column }: EmojiCell,
  key: string,
  toGridEdge: boolean
): EmojiCell | null {
  const lastRow = rowLengths.length - 1
  const lastColumn = (target: number) => rowLengths[target] - 1
  const sameColumnIn = (target: number) => ({
    row: target,
    column: Math.min(column, lastColumn(target)),
  })

  switch (key) {
    case "ArrowRight":
      if (column < lastColumn(row)) return { row, column: column + 1 }
      return row < lastRow ? { row: row + 1, column: 0 } : { row, column }
    case "ArrowLeft":
      if (column > 0) return { row, column: column - 1 }
      return row > 0
        ? { row: row - 1, column: lastColumn(row - 1) }
        : { row, column }
    case "ArrowDown":
      return sameColumnIn(Math.min(row + 1, lastRow))
    case "ArrowUp":
      return sameColumnIn(Math.max(row - 1, 0))
    case "Home":
      return toGridEdge ? { row: 0, column: 0 } : { row, column: 0 }
    case "End":
      return toGridEdge
        ? { row: lastRow, column: lastColumn(lastRow) }
        : { row, column: lastColumn(row) }
    case "PageDown": {
      const next = sectionStarts.find((start) => start > row)
      return next === undefined
        ? { row: lastRow, column: lastColumn(lastRow) }
        : { row: next, column: 0 }
    }
    case "PageUp":
      return {
        row: sectionStarts.findLast((start) => start < row) ?? 0,
        column: 0,
      }
    default:
      return null
  }
}

export function addRecent(recent: string[], hexcode: string) {
  return [hexcode, ...recent.filter((item) => item !== hexcode)].slice(
    0,
    MAX_RECENT
  )
}

export function readPreferences(): EmojiPreferences {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}")
    return {
      recent: Array.isArray(stored.recent) ? stored.recent : [],
      skinTone: [0, 1, 2, 3, 4, 5].includes(stored.skinTone)
        ? stored.skinTone
        : undefined,
    }
  } catch {
    return { recent: [] }
  }
}

export function writePreferences(preferences: EmojiPreferences) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(preferences))
  } catch {
    return
  }
}
